CREATE FUNCTION touch_updated() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE stores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, country text NOT NULL CHECK(country IN ('NZ','AU')), currency text NOT NULL CHECK(currency IN ('NZD','AUD')), timezone text NOT NULL DEFAULT 'Pacific/Auckland', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text, phone text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ref text NOT NULL UNIQUE, store_id uuid NOT NULL REFERENCES stores, customer_id uuid NOT NULL REFERENCES customers, device text NOT NULL, serial text, fault text NOT NULL, technician text NOT NULL DEFAULT 'Unassigned', status text NOT NULL DEFAULT 'assessment' CHECK(status IN ('assessment','approved','repairing','parts','ready','collected','cancelled')), received_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, due_on date, ready_at timestamptz, collected_at timestamptz, last_contact_at timestamptz, quote_cents integer CHECK(quote_cents>=0), invoice_cents integer CHECK(invoice_cents>=0), paid_cents integer CHECK(paid_cents>=0), approval_ref text, condition text, stores_data boolean NOT NULL DEFAULT true, refurbished_possible boolean NOT NULL DEFAULT false, notice_at timestamptz, notice_ref text, notice_data_loss boolean NOT NULL DEFAULT false, notice_refurbished boolean NOT NULL DEFAULT false, qa_note text, qa_by text, warranty_until date, imported boolean NOT NULL DEFAULT false, source_key text UNIQUE, source_data jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES stores, sku text NOT NULL, name text NOT NULL, on_hand integer NOT NULL DEFAULT 0 CHECK(on_hand>=0), reorder_at integer NOT NULL DEFAULT 0 CHECK(reorder_at>=0), unit_cost_cents integer NOT NULL DEFAULT 0 CHECK(unit_cost_cents>=0), supplier text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id,sku));
CREATE TABLE part_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets, part_id uuid NOT NULL REFERENCES parts, quantity integer NOT NULL CHECK(quantity>0), unit_cost_cents integer NOT NULL CHECK(unit_cost_cents>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets, actor text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets, issue text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), follow_up_on date NOT NULL, resolution text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['stores','customers','tickets','parts','part_usage','events','claims'] LOOP EXECUTE format('CREATE TRIGGER touch BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated()',t); END LOOP; END $$;
CREATE VIEW v_bench AS SELECT t.id,t.ref,s.name AS store,s.country,s.currency,c.name AS customer,t.device,t.fault,t.technician,t.status,t.due_on,t.quote_cents,t.invoice_cents,t.paid_cents,t.invoice_cents-t.paid_cents AS balance_cents,coalesce(u.parts_cents,0) AS parts_cents,t.invoice_cents-coalesce(u.parts_cents,0) AS contribution_before_labour_cents,
 (now() AT TIME ZONE s.timezone)::date-t.due_on AS days_late,
 floor(extract(epoch FROM (now()-t.last_contact_at))/86400)::int AS days_since_contact,
 floor(extract(epoch FROM (now()-t.ready_at))/86400)::int AS ready_days,t.imported
 FROM tickets t JOIN stores s ON s.id=t.store_id JOIN customers c ON c.id=t.customer_id LEFT JOIN (SELECT ticket_id,sum(quantity*unit_cost_cents)::int AS parts_cents FROM part_usage GROUP BY ticket_id)u ON u.ticket_id=t.id;
CREATE VIEW v_parts AS SELECT p.id,s.name AS store,s.currency,p.sku,p.name,p.on_hand,p.reorder_at,p.unit_cost_cents,p.supplier FROM parts p JOIN stores s ON s.id=p.store_id;
CREATE VIEW v_claims AS SELECT c.id,t.ref,b.customer,b.store,c.issue,c.status,c.follow_up_on,c.resolution,(now() AT TIME ZONE s.timezone)::date-c.follow_up_on AS days_late FROM claims c JOIN tickets t ON t.id=c.ticket_id JOIN stores s ON s.id=t.store_id JOIN v_bench b ON b.id=t.id;
CREATE VIEW v_compliance AS
 SELECT t.id,t.ref,'AU-NOTICE' AS rule,'Written repair notice evidence missing or later than acceptance' AS finding FROM tickets t JOIN stores s ON s.id=t.store_id WHERE s.country='AU' AND t.status NOT IN ('assessment','cancelled') AND (t.stores_data OR t.refurbished_possible) AND (t.accepted_at IS NULL OR t.notice_at IS NULL OR t.notice_at>t.accepted_at OR nullif(trim(t.notice_ref),'') IS NULL OR (t.stores_data AND NOT t.notice_data_loss) OR (t.refurbished_possible AND NOT t.notice_refurbished))
 UNION ALL SELECT id,ref,'INT-APPROVAL','Approval evidence missing' FROM tickets WHERE status NOT IN ('assessment','cancelled') AND nullif(trim(approval_ref),'') IS NULL
 UNION ALL SELECT id,ref,'INT-QA','Quality check or checker missing' FROM tickets WHERE status IN ('ready','collected') AND (nullif(trim(qa_note),'') IS NULL OR nullif(trim(qa_by),'') IS NULL)
 UNION ALL SELECT t.id,t.ref,'NZ-SERVICE','Promised repair date missed; review agreed timeframe and remedy' FROM tickets t JOIN stores s ON s.id=t.store_id WHERE s.country='NZ' AND t.status NOT IN ('ready','collected','cancelled') AND t.due_on<(now() AT TIME ZONE s.timezone)::date
 UNION ALL SELECT t.id,t.ref,'INT-CLAIM','Customer remedy follow-up overdue' FROM claims c JOIN tickets t ON t.id=c.ticket_id JOIN stores s ON s.id=t.store_id WHERE c.status='open' AND c.follow_up_on<(now() AT TIME ZONE s.timezone)::date;
